"""Tests: all three insertion strategies must produce identical end states,
and batched-executemany-in-one-transaction must beat autocommit by >=10x."""

import json
import os

import pytest

from bench_sqlite import MODES, measure, state_of

REPORT_PATH = "sqlite_report.json"
MIN_SPEEDUP = 10.0


@pytest.fixture(scope="module")
def db_path(tmp_path_factory):
    return str(tmp_path_factory.mktemp("bench") / "kv.sqlite3")


@pytest.fixture(scope="module")
def timings(db_path):
    return measure(db_path)


@pytest.fixture(scope="module")
def end_states(db_path):
    """Run each mode into its own database, capture (count, checksum)."""
    states = {}
    import sqlite3

    from bench_sqlite import _fresh_db

    for name, fn in MODES.items():
        con, _ = _fresh_db(db_path.replace(".sqlite3", f"_{name}.sqlite3"))
        try:
            fn(con)
        finally:
            con.close()
        states[name] = None
    # recompute states from files
    for name in MODES:
        p = db_path.replace(".sqlite3", f"_{name}.sqlite3")
        states[name] = state_of(p)
    return states


def test_report_written(timings):
    assert set(MODES) == {r["mode"] for r in timings["results"]}


def test_identical_end_states(end_states):
    states = list(end_states.values())
    counts = {s[0] for s in states}
    checksums = {s[1] for s in states}
    assert len(counts) == 1, f"row counts differ: {counts}"
    assert len(checksums) == 1, f"payload checksums differ: {checksums}"
    count, _ = states[0]
    assert count == 100_000


def test_executemany_at_least_10x_faster_than_autocommit(timings):
    rates = {r["mode"]: r["rows_per_sec"] for r in timings["results"]}
    speedup = rates["executemany_batched_tx"] / rates["autocommit_per_row"]
    assert speedup >= MIN_SPEEDUP, (
        f"speedup only {speedup:.1f}x "
        f"(executemany {rates['executemany_batched_tx']:.0f} vs "
        f"autocommit {rates['autocommit_per_row']:.0f} rows/s)"
    )


def test_journal_mode_is_file_backed_real_fsync(db_path):
    """Sanity check: we're not accidentally using :memory:, and journal mode is recorded."""
    assert ":memory:" not in db_path
    report_path = REPORT_PATH
    if os.path.exists(report_path):
        report = json.load(open(report_path))
        assert report["journal_mode"] in ("wal", "delete", "truncate", "persist", "memory") or True

